<?php
require_once __DIR__.'/config/db.php';
$tests=[]; if($pdo){$tests=$pdo->query("SELECT t.id,t.title,t.description,COUNT(q.id) question_count FROM online_tests t LEFT JOIN test_questions q ON q.test_id=t.id WHERE t.is_active=1 GROUP BY t.id ORDER BY t.created_at DESC")->fetchAll();}
function htest($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online testlar — Algoritm</title><link rel="stylesheet" href="assets/css/style.css?v=8"><style>.tests-wrap{max-width:1100px;margin:60px auto;padding:20px}.test-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px}.test-card{padding:24px;border:1px solid #342027;background:#121216;border-radius:18px;transition:.25s}.test-card:hover{transform:translateY(-5px);border-color:#e50914;box-shadow:0 10px 35px #e5091420}.test-card h2{font-size:22px}.test-card p{color:#aaa;line-height:1.6}.test-meta{color:#ff4b59;font-size:13px;margin:14px 0}</style></head><body><header class="site-header"><a class="brand" href="index.php"><img class="brand-logo" src="assets/images/algoritm-logo.jpeg" alt="Algoritm"><span>ALGORITM<small>O‘quv markazi</small></span></a><nav><a href="index.php">Bosh sahifa</a><a href="index.php#kurslar">Kurslar</a><a class="nav-cta" href="tests.php">Online testlar</a></nav></header><main class="tests-wrap"><span class="eyebrow">BILIMINGIZNI SINANG</span><h1>Online testlar</h1><p>Testni tanlang, ma’lumotlaringizni kiriting va natijangizni darhol ko‘ring.</p><div class="test-grid"><?php foreach($tests as $t): ?><article class="test-card"><h2><?=htest($t['title'])?></h2><p><?=htest($t['description']??'Bilimingizni sinab ko‘ring.')?></p><div class="test-meta"><?= (int)$t['question_count']?> ta savol · A/B/C/D</div><?php if((int)$t['question_count']>0): ?><a class="button primary" href="take_test.php?id=<?=(int)$t['id']?>">Testni boshlash →</a><?php else: ?><span class="status status-pending">Savollar kiritilmagan</span><?php endif; ?></article><?php endforeach; ?><?php if(!$tests): ?><div class="test-card"><h2>Hozircha test yo‘q</h2><p>Administrator panelidan yangi test yaratish mumkin.</p></div><?php endif; ?></div><a class="button secondary" href="index.php" style="margin-top:24px">← Bosh sahifa</a></main><script src="assets/js/theme.js?v=8"></script></body></html>
